#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;
use owner::JournalOwner;use ingetrazo_core::mesh::Mesh;use glam::DVec3;
fn record(o:&JournalOwner,name:&str,out:&mut Vec<serde_json::Value>){let (u,r)=o.history_counts();out.push(serde_json::json!({"name":name,"vertices":o.mesh().vertices.iter().map(|v|v.position.to_array()).collect::<Vec<_>>(),"edges":o.mesh().edges.iter().map(|e|[e.v0,e.v1]).collect::<Vec<_>>(),"undo":u,"redo":r}));}
fn append(o:&mut JournalOwner,a:f64,b:f64){let mut t=o.begin();t.add_edge(DVec3::new(a,0.,0.),DVec3::new(b,0.,0.)).unwrap();o.commit(t).unwrap();}
fn main(){let mut o=JournalOwner::new(Mesh::new()).unwrap();let mut out=vec![];append(&mut o,0.,1.);record(&o,"append",&mut out);o.undo().unwrap();record(&o,"undo",&mut out);let t=o.begin();assert!(!o.commit(t).unwrap());record(&o,"noop-with-redo",&mut out);let mut t=o.begin();t.add_edge(DVec3::new(8.,0.,0.),DVec3::new(9.,0.,0.)).unwrap();drop(t);record(&o,"failure-with-redo",&mut out);o.redo().unwrap();record(&o,"redo",&mut out);for i in 0..2{o.undo().unwrap();record(&o,&format!("repeat-undo-{i}"),&mut out);o.redo().unwrap();record(&o,&format!("repeat-redo-{i}"),&mut out);}o.undo().unwrap();record(&o,"branch-undo",&mut out);append(&mut o,3.,4.);record(&o,"branch-new",&mut out);assert!(!o.redo().unwrap());record(&o,"branch-redo-refused",&mut out);println!("{}",serde_json::to_string_pretty(&out).unwrap());}
